package dev.nez.arksurvivalreturns.feature.creature;

import java.util.List;
import java.util.Map;
import java.util.UUID;

/**
 * The colour variants of every species, in order: each creature is drawn in one of them, picked from its UUID, from
 * {@code textures/entity/<id>_<variant>.png}. Only colourings a species' kind could have, as many as it needs.
 * Generated by {@code tools/import_creatures.py} from {@code ../Creatures/variants.json}: do not edit by hand; edit the
 * registry (rules: {@code Creatures/README.md}, Colour variants), repaint and rerun the import.
 */
public final class CreatureVariants {
    private static final Map<String, List<String>> BY_ID = Map.ofEntries(
            Map.entry("acrocanthosaurus", List.of("umber", "olive", "rust", "slate")),
            Map.entry("allosaurus", List.of("tan", "umber", "rust", "olive")),
            Map.entry("ankylosaurus", List.of("umber", "olive", "sand", "slate")),
            Map.entry("archaeopteryx", List.of("black", "umber", "slate", "rust")),
            Map.entry("argentavis", List.of("black", "umber", "slate", "tawny")),
            Map.entry("brontosaurus", List.of("slate", "umber", "olive", "sand")),
            Map.entry("carnotaurus", List.of("rust", "umber", "tan", "charcoal")),
            Map.entry("ceratosaurus", List.of("olive", "umber", "rust", "charcoal")),
            Map.entry("cnidaria", List.of("azure", "violet", "rose", "moon", "amber")),
            Map.entry("deinosuchus", List.of("olive", "swamp", "umber", "slate")),
            Map.entry("dilophosaur", List.of("green", "olive", "umber", "sand")),
            Map.entry("direwolf", List.of("timber", "arctic", "black", "russet")),
            Map.entry("dragon", List.of("red", "white", "black")),
            Map.entry("giganotosaurus", List.of("slate", "umber", "rust", "sand")),
            Map.entry("kaprosuchus", List.of("olive", "umber", "slate", "charcoal")),
            Map.entry("liopleurodon", List.of("slate", "abyss", "umber", "charcoal")),
            Map.entry("lystrosaurus", List.of("tan", "umber", "slate", "olive")),
            Map.entry("mammoth", List.of("brown", "umber", "ginger", "blond")),
            Map.entry("megalocerus", List.of("brown", "red", "grey", "fawn")),
            Map.entry("megalodon", List.of("slate", "abyss", "charcoal")),
            Map.entry("megapithecus", List.of("silverback", "black", "brown")),
            Map.entry("mosasaurus", List.of("slate", "abyss", "charcoal", "umber")),
            Map.entry("paraceratherium", List.of("slate", "umber", "sand")),
            Map.entry("parasaur", List.of("olive", "sand", "umber", "green")),
            Map.entry("pegomastax", List.of("green", "olive", "tan", "rust")),
            Map.entry("plesiosaur", List.of("slate", "abyss", "umber")),
            Map.entry("pteranodon", List.of("slate", "umber", "snow", "charcoal")),
            Map.entry("quetzal", List.of("slate", "umber", "snow", "charcoal")),
            Map.entry("ravager", List.of("grey", "umber", "black", "dun")),
            Map.entry("sabertooth", List.of("tawny", "sand", "snow", "sable")),
            Map.entry("sarco", List.of("olive", "umber", "slate", "swamp")),
            Map.entry("spinosaurus", List.of("olive", "umber", "slate", "sand")),
            Map.entry("terrorbird", List.of("umber", "slate", "black", "tawny")),
            Map.entry("therizinosaurus", List.of("tawny", "umber", "slate", "cream")),
            Map.entry("titanoboa", List.of("green", "umber", "black", "olive")),
            Map.entry("titanosaur", List.of("slate", "umber", "sand", "olive")),
            Map.entry("triceratops", List.of("olive", "slate", "umber", "sand")),
            Map.entry("tusoteuthis", List.of("crimson", "maroon", "violet", "pale")),
            Map.entry("tyrannosaurus", List.of("olive", "umber", "sand", "charcoal", "rust")),
            Map.entry("unicorn", List.of("white", "grey", "black", "bay", "chestnut", "palomino")),
            Map.entry("velociraptor", List.of("tan", "umber", "slate", "olive", "rust")));

    private CreatureVariants() {}

    /** The species' variants, in order. */
    public static List<String> of(Species species) {
        return of(species.id);
    }

    /** The variants of the species with this id, in order; empty for an unknown id. */
    public static List<String> of(String id) {
        return BY_ID.getOrDefault(id, List.of());
    }

    /** The index of the variant a creature is drawn in: a fixed pick from its UUID. */
    public static int pick(Species species, UUID uuid) {
        return Math.floorMod(uuid.hashCode(), Math.max(1, of(species).size()));
    }
}
